        ...interval,
        start: resolveSessionNumber(interval?.start),
        duration: resolveSessionNumber(interval?.duration),
        progress: resolveSessionNumber(interval?.progress)
      }))
    : [];
  if (savedSessionStore.currentFocusItem) {
