import path from "node:path";

const workspaceAliases: ReadonlyArray<{ dir: string; alias: string }> = [
  { dir: "client/actions", alias: "@nucleum/actions" },
  { dir: "client/components", alias: "@nucleum/components" },
  { dir: "client/datafn", alias: "@nucleum/datafn" },
  { dir: "client/elements", alias: "@21n/elements" },
  { dir: "client/extensions", alias: "@nucleum/extensions" },
  { dir: "client/features", alias: "@nucleum/features" },
  { dir: "client/layout", alias: "@21n/layout" },
  { dir: "client/persistence", alias: "@nucleum/persistence" },
  { dir: "client/products", alias: "@nucleum/products" },
  { dir: "client/stores", alias: "@nucleum/stores" },
  { dir: "client/types", alias: "@21n/types" },
  { dir: "client/utils", alias: "@21n/utils" },
  { dir: "shared/types", alias: "@21n/shared-types" },
  { dir: "shared/utils", alias: "@21n/shared-utils" },
  { dir: "schema", alias: "@nucleum/schema" }
].sort((left, right) => right.dir.length - left.dir.length);

/**
 * Resolve a repo file to the same Vite alias the app uses, so page.evaluate
 * imports share the running module instance instead of a second `/@fs` copy.
 */
export function resolveRepoFsImportPath(relativePath: string) {
  const normalized = relativePath.replace(/\\/g, "/");
  for (const { dir, alias } of workspaceAliases) {
    if (normalized === dir || normalized.startsWith(`${dir}/`)) {
      const rest = normalized
        .slice(dir.length)
        .replace(/^\//, "")
        .replace(/\.ts$/, "");
      return rest ? `${alias}/${rest}` : alias;
    }
  }
  const repoRoot = path
    .resolve(__dirname, "..", "..", "..", "..")
    .replace(/\\/g, "/");
