export function resolveRepoFsImportPath(relativePath: string) {
  const repoRoot = path
    .resolve(__dirname, "..", "..", "..", "..")
    .replace(/\\/g, "/");
  return `/@fs${repoRoot}/${relativePath}`;
}

/**
 * Resolve the HMR-stamped `/@fs` URL the running app already loaded so
 * page.evaluate imports the same module instance.
 */
export async function resolveLiveRepoFsImportPath(
  page: Page,
  relativePath: string
) {
  const bareFsPath = resolveRepoFsImportPath(relativePath);
  return page.evaluate(async (needlePath) => {
    const needle = needlePath.split("?")[0];
    for (const entry of performance.getEntriesByType("resource")) {
      try {
        const url = new URL(entry.name, location.origin);
        if (url.pathname === needle) {
          return `${url.pathname}${url.search}`;
        }
      } catch {}
    }
    const fileName = needle.split("/").pop();
    if (!fileName) return needlePath;
    const escapedName = fileName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const importRe = new RegExp(
      `["'](/@fs[^"']*${escapedName}(?:\\?t=\\d+)?)["']`
    );
    for (const entry of performance.getEntriesByType("resource")) {
      if (!entry.name.includes("/@fs")) continue;
      try {
        const source = await fetch(entry.name).then((response) =>
          response.text()
        );
        const match = source.match(importRe);
        if (match?.[1]) return match[1];
      } catch {}
    }
    return needlePath;
  }, bareFsPath);
}

